function UIBattlingCharactorBattleInfoDialog:Update()
    if self.booleanUpdateRunning == false then return end
    for i = 1, #self.charactorInfoLBList do
        --- 存活角色跟随
        if self.charactorInfoLBList[i].Env:GetCharactorAliveState() then
            local isSyncTxtComp = self.charactorInfoLBList[i].Env:CharacterNodeFollowingFun()
            if isSyncTxtComp then
                local roleId = self.charactorInfoLBList[i].Env:GetRoleId() 
                UIBattleBuffMgr:ListBuffNodesSyncTxtPos(roleId)
            end
        end
    end
end

