function UIBattlingCharactorBattleInfoDialog:InitComponent()
    if not IsNull(self.BossInfoRoot) then
        self.bossInfoPanelLB = self.BossInfoRoot:GetComponent(typeof(LuaBehaviour))
    end

    -- 读表获取被动buff的间隔时间
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting267)
    local row = tableFile:GetByPrimaryKey("passiveBuffIntervalTime")
    PASSIVE_BUFF_TIME = parse_number(row,"para", 0.5)

    row = tableFile:GetByPrimaryKey("passiveTypeIntervalTime")
    WaveIntervalTimer = parse_number(row,"para", 0.8)

    -- print("[战斗] time ", PASSIVE_BUFF_TIME, WaveIntervalTimer)
    self:InitTotalDamage()
end

