function UIBattlingCharactorBattleInfoDialog:HideAllCharactorInfoNode()
    for i = 1, #self.charactorInfoLBList do
        self.charactorInfoLBList[i].Env:SetGameObjectState(false)
    end
end

function UIBattlingCharactorBattleInfoDialog:ShowAllCharactorInfoNode()
    for i = 1, #self.charactorInfoLBList do
        if not self.charactorInfoLBList[i].Env.booleanIsHideInfo
                and self.charactorInfoLBList[i].Env:GetCharactorAliveState() then
            self.charactorInfoLBList[i].Env:StopCoShowNodeInSkillShow()
            self.charactorInfoLBList[i].Env:SetGameObjectState(true)
        end
    end
end

function UIBattlingCharactorBattleInfoDialog:BattleRequireInputFun()
    self:ShowAllCharactorInfoNode()
    
    self:CleanCoCheckTriggerShow()
    self.listIdsTrigger = nil
end

--- 表现层开始requireInput(在收到requireInput的战报之后，会先等待卡池补卡合卡动画全部播完，之后才会发送这个事件)
function UIBattlingCharactorBattleInfoDialog:BattleViewRequireInput()
    -- requireInput的时候会同步真实的sp点，如果在补卡合卡动画播放完成之前就同步的话，会导致sp点不一致
    -- 所以同步sp点的操作要等补卡合卡全部完成之后再做
    ---刷新当前所有人物的 SP 点
    if BattleViewMgr and BattleViewMgr.roleViews then
        for i, roleView in pairs (BattleViewMgr.roleViews) do
            if roleView then
                local roleAlive = not roleView:IsDead()
                if roleAlive then
                    local ltCharacterNode = self:GetCharacterNode(roleView.id)
                    if not IsNull(ltCharacterNode) then
                        -- print("[SP点] require input 同步点数")
                        ltCharacterNode:SetRealSpNum(roleView.ultraPoint)
                    end
                end
                --print("~___UI_Value_RoleSP:", roleView.id, roleView.ultraPoint)
            end
        end
    end
end

