---ActionOnBattleWaveChange
---切换波次时的操作
---@param data table @ {waveNum, camp} 波次、阵营 的数据
function UIBattlingCharactorBattleInfoDialog:ActionOnBattleWaveChange(data)
    local camp = data.camp
    local waveNum = data.waveNum
    if BattleInfo:IsUserCamp(camp) and waveNum == 1 then
        -- self:ChangeCanvasGroupState(0)
    end
    self:ClearEnemySkillCard() --清除 敌方技能卡
    -- 隐藏总伤害面板
    self:FuncOnBattleTurnChange()
end

---ChangeCanvasGroupState
---设置 界面透明度 状态
---@param state integer @ 0: 显示 1: 隐藏
function UIBattlingCharactorBattleInfoDialog:ChangeCanvasGroupState(state)
    local canvasGroupAlphaMax = state == 1
    self.CanvasGroup:DOFade(canvasGroupAlphaMax and 0 or 1, 0.25)
    self.booleanUpdateRunning = not canvasGroupAlphaMax
end

---ClearTempSPNode
---清理 临时 SPNode
function UIBattlingCharactorBattleInfoDialog:ClearTempSPNode()
    --- 还原角色回合开始的 Sp 点数
    for i = 1, #self.charactorInfoLBList do
        local characterInfoLB = self.charactorInfoLBList[i].Env
        if not IsNull(characterInfoLB) then
            local ultraPoint = 0
            for i, roleView in ipairs(BattleViewMgr.roleViews) do
                if roleView.id == characterInfoLB.roleId then
                    ultraPoint = roleView.ultraPoint
                end
            end
            -- print("[SP点] reset技能点")
            self.charactorInfoLBList[i].Env:SetRealSpNum(ultraPoint)
        end
    end
end

---ActionOnPlayerFinishInput
---在玩家完成输入时 的操作
function UIBattlingCharactorBattleInfoDialog:ActionOnPlayerFinishInput()
    self:ClearEnemySkillCard() --清除 敌方技能卡
    for i = 1, #self.charactorInfoLBList do
        if self.charactorInfoLBList[i].Env:GetCharactorAliveState() then
            self.charactorInfoLBList[i].Env:SetGameObjectState(false)
            self.charactorInfoLBList[i].Env:SetCGUseCardShow(false)
        end
    end
    self:StartCoCheckTriggerShow()
end

---ClearEnemySkillCard
---清除 敌方技能卡
function UIBattlingCharactorBattleInfoDialog:ClearEnemySkillCard()
    for i = 1, #self.listCharacterCard do
        self.listCharacterCard[i]:RecycleSelf()
    end
    self.listCharacterCard = nil
    self.listCharacterCard = {}
end

---ShowEnemySkillCard
---展示 敌方技能卡
---@param data table {skillIndex = 1, targetId = 1, star = 1, roleId = 1, combo = 1}
function UIBattlingCharactorBattleInfoDialog:ShowEnemySkillCard(data)
    self:ClearEnemySkillCard()
    for i = 1, #data do
        local skillData = {
            skillIndex = data[i].skillIndex,
            targetId = data[i].targetId,
            star = data[i].star,
            roleId = data[i].roleId,
            combo = data[i].combo
        }
        for j = 1, #self.charactorInfoLBList do
            if self.charactorInfoLBList[j].Env:GetRoleId() == skillData.roleId then
                local isBoss = self:IsBoss(skillData.roleId)
                local infoNode = isBoss and self.bossInfoPanelLB.Env or self.charactorInfoLBList[j].Env
                local charactorUseCardRoot = isBoss and infoNode:GetBossSkillCardRoot() or infoNode:GetCharactorUseCardRoot()
                infoNode:SetCGUseCardShow(true)
                local enemyCardGO = UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.PATH_ENEMYSKILLCARD_GO, charactorUseCardRoot)
                local enemyCardNode = GetLuaBehaviour(enemyCardGO, Constants.UIBattlingLuaTablePath.EnemySKillCardNode)
                local lbEnemyCardNode = enemyCardNode.Env
                lbEnemyCardNode:SetSkillCardInfo(skillData)
                table.insert(self.listCharacterCard, lbEnemyCardNode)
            end
        end
    end
end

---OnSkillShowStart
---技能释放开始
---@param data table
function UIBattlingCharactorBattleInfoDialog:OnSkillShowStart(data)
    if #self.charactorInfoLBList <= 0 then return end
    local skillIndex = checkNumber(data.skillIndex)
    local roleId = checkNumber(data.roleId)
    local isUltra = UIBattlingDataMgr:GetSkillIsUltra(skillIndex, roleId)
    if isUltra then
        Events.Broadcast(Constants.EventNames.UIBattlingDialogShowState, false)
        if self:HasFatherBoss() then
            self.bossInfoPanelLB.Env:SetBossPanelShowState(false)
        end
        self:HideAllTotalDamagePanel()
    end
    -- print("->UIBattlingCharactorBattleInfoDialog:OnSkillShowStart_isUltra:", isUltra)

    local roleCamp = UIBattlingDataMgr:GetRoleCampByRoleId(data.roleId)
    if not BattleInfo:IsUserCamp(roleCamp) then
        self:HideAllTotalDamagePanel()
    end
end

---OnSkillShowEnd
---技能释放结束
---@param data table
function UIBattlingCharactorBattleInfoDialog:OnSkillShowEnd(data)
    ---SP 技能显示战中UI面板
    local roleId = checkNumber(data.roleId)
    local skillId = checkNumber(data.skillId)
    local stars = checkNumber(data.star)
    local skillData = checkTable(Core:GetSkillData(skillId, stars, 1))
    local skillIndex = checkNumber(skillData.action)
    local isUltra = UIBattlingDataMgr:GetSkillIsUltra(skillIndex, roleId)
    if isUltra then
        Events.Broadcast(Constants.EventNames.UIBattlingDialogShowState, true)
        ---//TODO 需要预防 先出现Boss波次后，后面波次没有Boss，需要对字段进行管理
        if self:HasFatherBoss() then
            self.bossInfoPanelLB.Env:SetBossPanelShowState(true)
        end
    end
    -- print("->UIBattlingCharactorBattleInfoDialog:OnSkillShowEnd_isUltra:", isUltra)
end

--- 技能的最后一个打击点时触发
---@param data any
function UIBattlingCharactorBattleInfoDialog:OnSkillLastHitPoint(data)
    local roleId = checkNumber(data.roleId)
    local skillId = checkNumber(data.skillId)

    local roleCamp = UIBattlingDataMgr:GetRoleCampByRoleId(data.roleId)
