---InitCharactorInfoNode
---初始化 人物信息 游戏物体
---@param data table
function UIBattlingCharactorBattleInfoDialog:InitCharactorInfoNode(data)
    for i = 1, #data do
        if IsNull(data[i].id) or IsNull(data[i].data) then return end
        -- print("[血条] role data", table.dump(data[i], nil, 3))
        local characterId = data[i].id
        local roleData = data[i].data

        local prefabPath
        local roleCampType = UIBattlingDataMgr:GetRoleCampByRoleId(characterId)
        if roleCampType == Constants.Camp.One  then
            prefabPath = Constants.UIBattlingObjPoolPrefabs.PATH_CHARACTERINFONODE_GO
        elseif roleCampType == Constants.Camp.Two then
            local roleType = roleData.type
            if roleType == 1 then
                prefabPath = Constants.UIBattlingObjPoolPrefabs.PATH_CHARACTERINFONODE_GO
            elseif roleType == 2 then
                prefabPath = Constants.UIBattlingObjPoolPrefabs.PATH_BOSSINFONODE_GO
            else
                prefabPath = Constants.UIBattlingObjPoolPrefabs.PATH_CHARACTERINFONODE_GO
            end
        end

        local goCharacterNode = UIBattlingTools.ReloadPoolObjGO(prefabPath)
        goCharacterNode.name = string.format("%s_%d", "CharactorInfoNode", characterId)
        local charactorInfoNode = GetLuaBehaviour(goCharacterNode, Constants.UIBattlingLuaTablePath.UIBattlingCharactorNode)
        if not IsNull(charactorInfoNode) then
            charactorInfoNode:Init()
            local roleView = BattleViewMgr:FindRoleView(characterId)
          
            local CharactorInfoPos = roleView.transform
            local go = charactorInfoNode.gameObject
            local t = go:GetComponent(typeof(RectTransform))
            KTool.SetParent(go, self.CharactorInfoNodeRoot.gameObject)
            local scale = CharactorInfoPos.localScale
            local colliderCenterY = roleView.centerY * scale.y * 2 + 0.3
            
            local v3 =  Vector3.New(CharactorInfoPos.position.x, colliderCenterY, CharactorInfoPos.position.z)
            local posInScreen = UIBattlingTools.WorldPointToUIPoint(v3, self.CharactorInfoNodeRoot)
            t.anchoredPosition = Vector2.New(posInScreen.x, posInScreen.y)

            local modelVo = roleView.modelVo
            local floatWordY = checkNumber(checkTable(modelVo.floatWord).y)
            local v3Center = Vector3.New(CharactorInfoPos.position.x, CharactorInfoPos.position.y + floatWordY, CharactorInfoPos.position.z)
            local posHit = UIBattlingTools.WorldPointToUIPoint(v3Center, self.CharactorInfoNodeRoot)
            local valueY =posHit.y - posInScreen.y
            --t.anchoredPosition = Vector2.New(posInScreenCenter.x, posInScreenCenter.y)
            
            local characterData
            --local path = BattleViewMgr:GetPath(not (roleCampType == Constants.TargetCamp.Friend))
            --local cinemachinePath = path:GetComponent(typeof(CS.Cinemachine.CinemachinePathBase))
            --local posZero = cinemachinePath:EvaluatePosition(0)
            --local cameraMain = BattleViewMgr.camera
            --local cameraPos = cameraMain.transform.position
            --local distance = (CharactorInfoPos.position - cameraPos).sqrMagnitude
            --charactorInfoNode.Env:SetCharacterInfoRootScale(UIBattlingTools.GetCharacterNodeScale(roleCampType, distance))
            characterData = UIBattlingDataMgr:SetTeamData(roleCampType, roleData, characterId,
                roleCampType == Constants.Camp.One and BattleViewMgr.nowSelfWave or BattleViewMgr.nowWave)
            local roleHpStart
            local roleAttrData = checkTable(roleView.attr)
            if roleAttrData.class and roleAttrData.class.SetValue then
                local roleHpNow = roleAttrData:GetValue(Constants.AttrTypeId.NowHp)
                local roleHpMax = roleAttrData:GetValue(Constants.AttrTypeId.Hp) -- 角色入场血量上限
                roleHpStart = roleHpNow / roleHpMax
            end

            local rootHit = charactorInfoNode.Env.HitJumpNumRoot
            local jumpNodePosition = rootHit.anchoredPosition
            local aPosHit = Vector2.New(jumpNodePosition.x, jumpNodePosition.y + valueY)
            rootHit.anchoredPosition = aPosHit
            
            local hpCharacter = roleHpStart ~= nil and roleHpStart or characterData.hpPreInBattleStart -- 角色初始 HP
            local spCharacter = characterData.spInBattleStart -- 角色初始 SP
            local lv = characterData.level
            local type = characterData.enemyType
            local attriType = characterData.attrType
            local characterSPMax = checkNumber(isSet(roleData, "maxSP") and roleData.maxSP or 6) -- 角色 SP 上限
            --- 人物信息 Data
            local charactorData = {
                battleFieldId = characterId,
                AttrType = attriType,
                HpPreInBattleStart = hpCharacter,
                SpInBattleStart = spCharacter,
                SpMax = characterSPMax,
                isPlayer = roleView.isPlayer,
            }
            --- Boss类型隐藏战场血条
            if not BattleInfo:IsUserCamp(roleCampType) then
                if type == 2 then
                    --- 初始化 节点激活
                    self.bossId = characterId
                    self.bossType = type
                    charactorInfoNode.Env.booleanIsBoss = true
                    charactorData.multiNum = UIBattlingDataMgr:GetBossHPMultiNum(BattleViewMgr.initData.questId, BattleViewMgr.nowWave)
                elseif type == 3 then
                    self.bossId = characterId
                    self.bossType = type
                    local bossData = {
                        bossId = characterId,
                        bossLv = lv,
                        bossAttri = attriType,
                        bossHp = hpCharacter,
                        bossSp = spCharacter,
                        SpMax = characterSPMax,
                        multiNum = UIBattlingDataMgr:GetBossHPMultiNum(BattleViewMgr.initData.questId, BattleViewMgr.nowWave)
                    }
                    -- self.bossInfoPanelLB:Init()
                    self.bossInfoPanelLB.Env:SetBossInfoPanel(bossData)
                end
            end
            charactorInfoNode.Env:SetCharactorInfo(charactorData)
            charactorInfoNode.Env:SetRootFather(self.CharactorInfoNodeRoot)
            charactorInfoNode.gameObject.name = "CharactorNode_" .. characterId
            table.insert(self.charactorInfoLBList, charactorInfoNode)
            
            charactorInfoNode.Env:SetNodeShowState(type == 3 and 2 or 1)
            charactorInfoNode.Env:SetGameObjectState(false)     -- 初始显示状态设置为隐藏
            --- 设置角色 SP 点数
            -- local charactorSpData = {
            --     roleId = characterId,
            --     point = spCharacter
            -- }
            -- self:OnCharactorSpChange(charactorSpData)
            charactorInfoNode.Env:SetRealSpNum(spCharacter, false)

            --- 获取人物缓存的 buffData
            local buffDataBeforeInit = UIBattlingCtrlMgr:GetInstance():GetBuffDataBeforeRoleInit(characterId)
            if not IsNull(buffDataBeforeInit) and #buffDataBeforeInit >= 0 then
                for i = 1, #buffDataBeforeInit do
                    self:SetCharacterBuffIcon(charactorInfoNode, buffDataBeforeInit[i])
                end
            end
        end
    end
end

---RecycleCharactorInfoNode
---角色死亡 角色信息面板 Fun
---@param data table
function UIBattlingCharactorBattleInfoDialog:RecycleCharactorInfoNode(data)
    -- 这个消息只在切换波次和断线重连的时候进来

    -- 断线重连的时候会传进来data
    for i = 1, #data do
        for j = 1, #self.charactorInfoLBList do
            if data[i] == self.charactorInfoLBList[j].Env:GetRoleId() then
                self.charactorInfoLBList[j].Env:RecycleCharactorNode()
                table.remove(self.charactorInfoLBList, j)
                break
            end
        end
    end

    -- 切换波次的时候data为空，遍历血条，没血的都回收掉
    local needRecycle = {}
    for j = 1, #self.charactorInfoLBList do
        if self.charactorInfoLBList[j].Env:GetCharactorAliveState() == false then
            table.insert(needRecycle, j)
        end
    end

    for i, index in fipairs(needRecycle) do
        -- 如果是boss，把左上角boss关掉
        local roleId = self.charactorInfoLBList[index].Env:GetRoleId()
        if self:IsBoss(roleId) then
            self.bossInfoPanelLB.Env:SetBossPanelShowState(false)
        end
        -- 回收小血条
        self.charactorInfoLBList[index].Env:RecycleCharactorNode()
        table.remove(self.charactorInfoLBList, index)
    end
end

---OnBattleChangeElement
---角色属性变换 监听执行函数
---@param data table {roleId = 1, element = 1}
function UIBattlingCharactorBattleInfoDialog:OnBattleChangeElement(data)
    local roleId = data.roleId
    local elementType = data.element
    for i = 1, #self.charactorInfoLBList do
        local ltCharacterNode = self.charactorInfoLBList[i].Env
        if ltCharacterNode then
            local characterId = ltCharacterNode:GetRoleId()
            local characterAliveState = ltCharacterNode:GetCharactorAliveState()
            if roleId == characterId and characterAliveState then
                --- 设置 mapCharacterAttribute 角色属性字段
                UIBattlingDataMgr:SetCharacterAttri(roleId, elementType)
                ltCharacterNode:SetCharactorAttriType(elementType)
                --- 检测怪物是否为 Boss
                if self:IsBoss(roleId) then
                    local lbBossInfoPanelLB = self.bossInfoPanelLB.Env
                    lbBossInfoPanelLB:SetBossAttribute(elementType)
                end
                --- 角色相关 SkillCard 转换图标
                local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
                battlingDialog:ChangeSkillCardsAttributeTypeByRoleId(roleId, elementType)
                break
            end
        end
    end
end

