---StartCoCheckTriggerShow
---开始检测协程 1.技能表现开始开启 
function UIBattlingCharactorBattleInfoDialog:StartCoCheckTriggerShow()
    self:CleanCoCheckTriggerShow()
    self.coCheckTriggerShow = cs_coroutine.start(function()
        while true do
            self:UpdateListTriggerStatus()
            cs_coroutine.yield_return()
        end
    end)
end

---CleanCoCheckTriggerShow
---关闭检测协程  1.玩家输入结束 2.生命周期 D 结束
function UIBattlingCharactorBattleInfoDialog:CleanCoCheckTriggerShow()
    if self.coCheckTriggerShow then
        cs_coroutine.stop(self.coCheckTriggerShow)
        self.coCheckTriggerShow = nil
    end
end

function UIBattlingCharactorBattleInfoDialog:UpdateListTriggerStatus()
    if isNull(self.listIdsTrigger) then return end
    local timeNow = TimeUtils.GetTime(false)
    for i = 1, #self.listIdsTrigger do
        local data = self.listIdsTrigger[i]
        local timeStart = data.timeStart
        local timeOut = timeNow >= timeStart + CD_TRIGGER_IMG_SHOW * BattleViewMgr.gameSpeed
        if data.inCD and timeOut then
            data.inCD = false
        end
    end
end

function UIBattlingCharactorBattleInfoDialog:CheckListIdsTrigger(data)
    if isNull(self.listIdsTrigger) then self.listIdsTrigger = {} end
    local triggerBuffTypeId = data.triggerBuffTypeId
    local roleId = data.roleId
    for i = 1, #self.listIdsTrigger do
        local triggerData = self.listIdsTrigger[i]
        if roleId == triggerData.roleId and triggerBuffTypeId == triggerData.triggerBuffTypeId then
            if not triggerData.inCD then
                local timeNow = TimeUtils.GetTime(false)
                triggerData.timeStart = timeNow
                triggerData.inCD = true
                return true
            end
            return false
        end
    end
    local timeStart = TimeUtils.GetTime(false)
    local dataTriggerShow = TriggerShowData.New(roleId, triggerBuffTypeId, timeStart, true)
    table.insert(self.listIdsTrigger, dataTriggerShow)
    return true
end

