---CharactorTempSPAdd
--- 角色临时 SP 点 变化
---@param data table
function UIBattlingCharactorBattleInfoDialog:CharactorTempSPAdd(data)
    if isNull(data.p) then
        return
    end
    --- 确定 SP 添加的角色
    local charactorId = data.p[1]
    --- 确定 SP 添加的点数
    local numSPPoint = data.p[2]
    -- print("[加点]", table.dump(data, nil, 3))
    if checkNumber(numSPPoint) <= 0 then return end
    --- 设置临时技能点
    for i = 1, #self.charactorInfoLBList do
        if self.charactorInfoLBList[i].Env:GetRoleId() == charactorId then
            local ultraPointType = 1
            local roleView = BattleViewMgr:FindRoleView(charactorId)
            if roleView then
                ultraPointType = roleView.ultraPointType
            end
            if data.r == Constants.RecordType.UnitCard then
                -- print("[SP点] 合卡加点")
                if ultraPointType == 1 then
                    self.charactorInfoLBList[i].Env:SetGameObjectState(true)
                    self.charactorInfoLBList[i].Env:AddRealSpNum(numSPPoint)
                end
            elseif data.r == Constants.RecordType.UseCard then
                -- print("[SP点] 出卡虚点")
                self.charactorInfoLBList[i].Env:SetGameObjectState(true)
                if ultraPointType == 2 then
                    local realNum = self.charactorInfoLBList[i].Env:GetCharacterSpInfo()
                    if realNum > 0 then
                        self.charactorInfoLBList[i].Env:SubRealSpNum(numSPPoint)
                        self.charactorInfoLBList[i].Env:AddTempSpNum(numSPPoint)
                    end
                else
                    self.charactorInfoLBList[i].Env:AddTempSpNum(numSPPoint)
                end
            end
        end
    end
end

---OnCharactorSpChange
---角色 Sp 点数变化
---@param data table
function UIBattlingCharactorBattleInfoDialog:OnCharactorSpChange(data)
    local index = data.roleId
    local spPoint = data.point
    local originType = data.type
    -- print("->UIBattlingCharactorBattleInfoDialog:OnCharactorSpChange", table.dump(data))
    if originType == Constants.AddSPType.Skill
    or originType == Constants.AddSPType.SkillEffect then
        for i = 1, #self.charactorInfoLBList do
            if self.charactorInfoLBList[i].Env:GetRoleId() == index then
                
                 -- 如果是来自于技能效果，还要额外有一个跳字
                if originType == Constants.AddSPType.SkillEffect then
                    self.charactorInfoLBList[i].Env:ShowSPChangeDesc(spPoint)
                end

                -- 更新SP点
                -- print("[SP点] 技能填点")
                if self:IsBoss(index) then
                    local bossData = { bossSP = spPoint }
                    local bossMsg = { type = 3, data = bossData }
                    Events.Broadcast(Constants.EventNames.UIBattlingBossMsg, bossMsg)
                end
                
                local ultraPointType = 1
                local roleView = BattleViewMgr:FindRoleView(index)
                if roleView then
                    ultraPointType = roleView.ultraPointType
                end

                if ultraPointType == 1 then
                    self.charactorInfoLBList[i].Env:SetRealSpNum(spPoint, true)
                elseif ultraPointType == 2 then
                    self.charactorInfoLBList[i].Env:SubTempSpNum(1)
                end
                
                -- 显示一下血条
                self.charactorInfoLBList[i].Env:SetNodeInSkillShow()
                break
            end
        end
       
    elseif originType == Constants.AddSPType.UnitCard then
       -- 忽略合卡增加点数的战报，使用表现层合卡的战报进行加点
    end
end

