---ShowDamageValue
---伤害数值展示
---@param data table {roleId = 1, damage = 200(正数伤害，负数治疗), isHeal = true(是否治疗),isCrit = true(是否暴击),isHit = true(是否命中), isDot = false(是否是dot), dotType = 1}
function UIBattlingCharactorBattleInfoDialog:ShowDamageValue(data)
    local roleCamp = UIBattlingDataMgr:GetRoleCampByRoleId(data.roleId)
    for i = 1, #self.charactorInfoLBList do
        if self.charactorInfoLBList[i].Env:GetRoleId() == data.roleId then
            --- 针对 Boss 血条的改动
            if self:IsBoss(data.roleId) then
                self.bossInfoPanelLB.Env:SetBossPanelShowState(true)
            end
            --- 更新跳字出现位置
            self.charactorInfoLBList[i].Env:UpdateJumpNodePos()
            ---找到 对应显示 的 人物，返回对应显示位置
            local hitJumpNodePos = self.charactorInfoLBList[i].Env.rootHitAPosition
            local rootHit = self.charactorInfoLBList[i].Env.HitJumpNumRoot
            ---找到 节点对应的 层级 位置
            --local hitJumpNodeLayer = self.JumpNodeShowRoot
            --self:ReloadJumpNode(data, hitJumpNodeTrans, hitJumpNodeLayer)
            self:ReloadJumpNodeSetParent(data, rootHit, hitJumpNodePos)
        end
    end

    -- 目标为非敌方阵营的伤害不计入
    if BattleInfo:IsUserCamp(roleCamp) then return end 

    --- 治疗暂不显示 总伤害
    if data.isDot or data.damage < 0 then return end

    --- 判断是否显示 总伤害节点
    if self.totalDamageValue == 0 then
        self.curSkillTotalDamageNode = self:GetUnusedTotalDamageNode()
        self.curSkillTotalDamageNode:ShowPanel()
    end

    --- 累计伤害
    local damageValueEx = self.totalDamageValue -- 在累计伤害之前的 伤害值
    local damageValueNow = self.totalDamageValue + data.damage + data.shieldAbsorb -- 累计之后的伤害值

    -- 添加千分位
    local strDV = checkString(math.ceil(damageValueNow)) -- 展示值
    local listChar = {}
    for c in strDV:gmatch"." do
        table.insert(listChar, c)
    end
    local index = 0
    for i = #listChar, 1, -1 do
        index = index + 1
        if index % 3 == 0 and i ~= 1 then
            table.insert(listChar, i, ",")
        end
    end
    local showValue = table.concat(listChar)
    self.curSkillTotalDamageNode:SetDamage(showValue)
    self.totalDamageValue = damageValueNow
end

function UIBattlingCharactorBattleInfoDialog:AddBuffJumpNode(buffEffectId, showId, buffData)
    local buffDes, buffValue = BattleViewMgr:GetBuffInfo(buffEffectId, showId, buffData.star, buffData.lv)
    --print("->AddBuffJumpNode:", buffDes, buffValue)
    if isNull(buffDes) then return end
    self:SetRoleBuffDesc(buffData.ownerId, buffDes, buffValue, buffData.buffType, buffData.id)
end

function UIBattlingCharactorBattleInfoDialog:SetRoleBuffDesc(roleId, buffDes, buffValue, buffType, buffId)
    for i = 1, #self.charactorInfoLBList do
        if self.charactorInfoLBList[i].Env:GetRoleId() == roleId then
            self.charactorInfoLBList[i].Env:FillShowBuffDesSequene(buffDes, buffValue, buffType, buffId)
            break
        end
    end
end

