---AddBuff
---添加 Buff
---@param data table @ {uid = 1,buffId = 1,ownerId = 1,lay = 1(层数),remain = 1(持续回合数),star = 1,lv = 1}
function UIBattlingCharactorBattleInfoDialog:AddBuff(data)
    -- print("->UIBattlingCharactorBattleInfoDialog:BuffAdd", table.dump(data))
    --- showId 判断
    local buffData = Core:GetBuffData(data.buffId, data.star, data.lv)
    buffData.ownerId = data.ownerId
    local showIds = buffData.showIds
    if isNull(showIds) or #showIds <= 0 then return end -- 数组数据判断
    local showId = showIds[1] -- 子楠兄 Said ~~
    if Tools.isNullKey(showId) then return end
    local showEffectVo = UIBattlingTools.GetBuffDataPath(showId)
    if isNull(showEffectVo) then return end
    local showText = showEffectVo.showText
    if checkInt(showText) > 0 then return end -- 配表规则 showText > 0 战中不显示
    local passiveShow = showEffectVo.passiveShow
    if checkInt(passiveShow) > 0 then return end -- 配表规则 passiveShow > 0 战中血条不显示图标_Rule_By_MDD

    -- 判断是否是被动buff
    -- 如果是类型为1.2.3的被动buff跳过
    -- 如果是类型为4的被动buff，缓存起来

    ---- Buff 飘字
    local buffEffectId = buffData.effects[1]
    if not Tools.isNullKey(buffEffectId) then
        self:AddBuffJumpNode(buffEffectId, showId, buffData)
    end
    local curCharactorLB
    for i = 1, #self.charactorInfoLBList do
        if self.charactorInfoLBList[i].Env:GetRoleId() == data.ownerId then
            curCharactorLB = self.charactorInfoLBList[i]
        end
    end
    if not IsNull(curCharactorLB) then
        --- 角色血条已创建
        self:SetCharacterBuffIcon(curCharactorLB, data)
    else
        --- 角色血条为创建/引用丢失, 缓存Buff信息
        UIBattlingCtrlMgr:GetInstance():InsertBuffData(data)
    end
end

---SetCharacterBuffIcon
---@param curCharactorLB UnityEngine.Component @ charactorNode
---@param data table @ buffData
function UIBattlingCharactorBattleInfoDialog:SetCharacterBuffIcon(curCharactorLB, data)
    local buffData = Core:GetBuffData(data.buffId, data.star, data.lv)
    local buffEffectId = buffData.showIds[1] -- 子楠兄 Said ~~ 
    local buffVo = UIBattlingTools.GetBuffDataPath(buffEffectId)
    --- 如 效果表现表 无法找到相应 buff 则不实例化数据
    if IsNull(buffVo) then return end
    --- buffIconPath
    local buffIconPath = buffVo.icon --- 获取 buffIcon 资源路径
    if string.isEmpty(buffIconPath) then return end
    local buffTargetId = data.ownerId -- 目标Id
    local buffMainId = data.uid -- buffIndexId
    local buffRemainNum = data.remain -- Buff剩余回合数
    local buffLayer = data.lay -- buff 层数
    local buffTypeId = data.buffId -- BuffTypeId
   
    local characterNode = curCharactorLB.Env
    local roleId = characterNode.roleId
    local isBoss = self:IsBoss(roleId)
    local buffFather = isBoss and self.bossInfoPanelLB.Env:GetBossBuffRoot() or characterNode:GetBuffRoot()
    
    local buffIconLB = self:ReloadBuffIconLB(buffFather, isBoss)
    
    if not IsNull(buffIconLB) then
        if buffIconPath then
            -- buffIconLB.Env:SetBuffIconIMG(buffIconPath)
            buffIconLB.Env:SetShowNodeActiveState(true)
            buffIconLB.Env:InitBuffNode(buffTypeId, buffData.round, buffIconPath)
            buffIconLB.Env:SetNodeTxt(buffRemainNum, buffLayer) -- 设置 BuffNode 的 TXT
        end
        --- 获取所属人物信息面板的显示状态控制 Txt 节点的显示状态
        if curCharactorLB.Env:GetCharactorInfoRootShowState() == false then
            -- 这里为什么只false了round？
            buffIconLB.Env:SetRoundTxtActiveState(false)
        end
        --- 判断是否分层
        --if (not booleanIsBoss) and buffRemainNum < 999 then
        --    --- 设置 buffNodeText
        --    buffIconLB.Env:SetNodeTxtFather(self.CharactorInfoNodeLvInfoRoot)
        --end
    end
    UIBattleBuffMgr:ActionOnAddBuff(buffMainId, buffTypeId, buffTargetId, buffLayer, buffIconLB, data.star, data.lv)
    self:SetRoleBuffNodesSequence(curCharactorLB.Env:GetRoleId())
end

---ReloadBuffIconLB
---使用 BuffIcon LB
---@param pos Vector2
function UIBattlingCharactorBattleInfoDialog:ReloadBuffIconLB(rect, isBoss)
    local buffNodeGO = UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.PATH_BUFFNODE_GO, rect)
    local buffNodeLB = GetLuaBehaviour(buffNodeGO, Constants.UIBattlingLuaTablePath.UIBattlingCharactorBuffNode)
    if IsNull(buffNodeLB.Env) then
        buffNodeLB:Init()
    end
    xTry(function()
        isBoss = checkBool(isBoss)
        if isBoss then
            buffNodeGO.transform:SetAsFirstSibling()
        end
    end)
    return buffNodeLB
end

---ChangeBuff
---Buff信息改变
---@param data table BuffData
function UIBattlingCharactorBattleInfoDialog:ChangeBuff(data)
    local buffMainId = data.uid -- buffIndexId
    if IsNull(buffMainId) then return end
    local buffVo = UIBattleBuffMgr:GetBuff(buffMainId)
    if buffVo then
        local buffData = Core:GetBuffData(buffVo.BuffId, buffVo.star, buffVo.lv)
        buffData.ownerId = data.ownerId
        local layEX = buffVo.layNum
        local buffEffectId = buffData.effects and buffData.effects[1] or nil
        local showId = buffData.showIds and buffData.showIds[1] or nil -- 子楠兄 Said ~~
        local condition = (not Tools.isNullKey(buffEffectId)) and (not Tools.isNullKey(showId)) and data.lay > buffVo.layNum
        -- print("->UIBattlingCharactorBattleInfoDialog:BuffChange",layEX, data.lay, checkString(condition))
        if condition then
            self:AddBuffJumpNode(buffEffectId, showId, buffData)
        end
    end
    UIBattleBuffMgr:ActionOnChangeBuff(data)
    xTry(function() 
        local roleId = data.ownerId
        self:SetRoleBuffNodesSequence(roleId)
    end)
end

---RemoveBuff
---Buff移除
---@param data table @ BuffData
function UIBattlingCharactorBattleInfoDialog:RemoveBuff(data)
    --print("~~vRemoveBuff" .. table.dump(data))
    local buffMainId = data.uid -- 移除 buff 的唯一 ID
    local roleId = data.ownerId
    if IsNull(buffMainId) then return end
    UIBattleBuffMgr:ActionOnRemoveBuff(data)
    self:SetRoleBuffNodesSequence(roleId)
end

