function UIBattlingCharactorBattleInfoDialog:GetCharacterSpInfo(roleId)
    for i, node in pairs(self.charactorInfoLBList) do
        local infoNode = node.Env
        if roleId == infoNode:GetRoleId() then
            return infoNode:GetCharacterSpInfo()
        end
    end
end

function UIBattlingCharactorBattleInfoDialog:GetCharacterNode(roleId)
    for i, node in pairs(self.charactorInfoLBList) do
        if node.Env:GetRoleId() == roleId then
            return node.Env
        end
    end
    return nil
end

------------ GetData ------------

function UIBattlingCharactorBattleInfoDialog:SetRoleBuffNodesSequence(roleId)
    local buffsList = UIBattleBuffMgr:GetRoleBuffList(roleId)
    if self:IsBoss(roleId) then
        self.bossInfoPanelLB.Env:SetBuffList(buffsList)
    else
        local characterNode = self:GetCharacterNode(roleId)
        if not isNull(characterNode) then
            characterNode:SetBuffIconSequence(buffsList)
        end
    end
end

function UIBattlingCharactorBattleInfoDialog:CleanRoleBuffNodes(roleId)
    local buffsList = UIBattleBuffMgr:GetRoleBuffList(roleId)
    for i, buffData in ipairs(buffsList) do
        if buffData then
            local lbBuffNode = buffData.luaBehaviour
            local ltBuffNode = lbBuffNode.Env
            ltBuffNode:RecycleBuffNode()
        end
    end
end

--- 开始展示被动buff
function UIBattlingCharactorBattleInfoDialog:ShowPassiveBuff()
    local passiveSkillList = self:MakePassiveSkillList()
    -- print("[战斗] 开场被动buff ", table.dump(passiveSkillList, nil, 5))
    
    -- 各种来源类型的播放顺序
    local playQueue = Constants.PassiveBuffShowOrder
    local typeCount = table.count(Constants.PassiveBuffShowOrder)
    
    self.coShowPassiveBuff = cs_coroutine.start(function()
        -- 开局展示被动buff
        for index = 1, typeCount, 1 do
            local skillOrigin = playQueue[index]
            -- print("[战斗] 被动 ", skillOrigin, typeCount)
            local roleSkillList = passiveSkillList[skillOrigin]
            if isNotNull(roleSkillList) and table.count(roleSkillList) > 0 then
                -- 给每一个角色展示被动
                local countMax = 0
                for i, skillList in pairs(roleSkillList) do
                    countMax = math.max(#skillList, countMax)
                    local LT_Role
                    for j = 1, #self.charactorInfoLBList do
                        if self.charactorInfoLBList[j].Env:GetRoleId() == i then
                            LT_Role = self.charactorInfoLBList[j].Env
                        end
                    end
                    if LT_Role then
                        if table.isContain(Constants.PassiveBuffWithHeadTopIcon, skillOrigin) then
                            -- 展示头顶icon的类型(区域光环的头顶icon是buff特效，不属于这种buffIcon)
                            LT_Role:ShowPassiveBuffIcon(skillOrigin, nil)
                        end
                        -- 把buff描述添加进队列
                        for j, skillInfo in ipairs(skillList) do
                            LT_Role:FillShowBuffSequence(self:MakeBuffDescVo(skillOrigin, skillInfo.buffId, skillInfo.buffStar))
                        end
                    end
                end
                -- print("[战斗] 跳 ", skillOrigin, typeCount)
                if index < typeCount then
                    -- 最后一波就不用等了，都一样
                    local singleTime = table.isContain(Constants.PassiveBuffWithHeadTopIcon, skillOrigin) and PASSIVE_BUFF_TIME or NormalBuffTime
                    -- print("[战斗] wait ", skillOrigin, countMax * singleTime + WaveIntervalTimer)
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(countMax * singleTime + WaveIntervalTimer))
                end
            end
        end
        self.coShowPassiveBuff = nil
    end)

    -- 计算展示buff需要的时间
    local waitTime = 0
    local skillCatPassiveWaitTime = 0
    local skillCatCountEnd = false
    for i = 1, typeCount, 1 do
        local skillOrigin = playQueue[i]
        local roleSkillList = passiveSkillList[skillOrigin]        
        if isNotNull(roleSkillList) and table.count(roleSkillList) > 0 then
            local countMax = 0
            for j, skillList in pairs(roleSkillList) do
                countMax = math.max(#skillList, countMax)
            end
            local singleTime = table.isContain(Constants.PassiveBuffWithHeadTopIcon, skillOrigin) and PASSIVE_BUFF_TIME or NormalBuffTime
            waitTime = waitTime + countMax * singleTime + WaveIntervalTimer
            -- 下面是统计猫球buff之前的被动buff需要的时间
            if (not skillCatCountEnd) then   
                if skillOrigin == Constants.PassiveBuffOrigin.CatBall then
                    skillCatCountEnd = true
                else
                    skillCatPassiveWaitTime = waitTime
                end
            end
        end
    end
    return waitTime, skillCatPassiveWaitTime
end
-- local UIBattlingCtrlMgr = import("Game.UI.UIBattling.UIBattlingCtrlMgr")
-- UIBattlingCtrlMgr:GetInstance():GetBattlingInfoDialog():ShowPassiveBuff()
function UIBattlingCharactorBattleInfoDialog:MakePassiveSkillList()
    local passiveSkillsList = {}
    local initData = BattleInfo.initData
    local roleDataList = initData.playerTeam[1]
    for i, roleData in ipairs(roleDataList) do
        local strPassiveSkill = roleData.passiveSkills
        -- strPassiveSkill = "110100801=1=1&110100802=1=1&110100801=1=1&110100802=1=1&110101101=1=2&110100501=1=2&110100502=1=3&110100503=1=3&99999=1=4"
        if (not IsNull(strPassiveSkill)) and strPassiveSkill ~= "" then
            local tPSList = string.split(strPassiveSkill, "&")
            for j, skill in ipairs(tPSList) do
                local result = string.split(skill, "=")
                local buffId = checkInt(result[1])
                local buffStar = checkInt(result[2])   
                local skillOrigin = checkInt(result[3]) -- 1、2、3、4
                if skillOrigin == 0 then
                    skillOrigin = Constants.PassiveBuffOrigin.Other
                end
                if isNull(passiveSkillsList[skillOrigin]) then
                    passiveSkillsList[skillOrigin] = {}
                end
                if isNull(passiveSkillsList[skillOrigin][roleData.id]) then
                    passiveSkillsList[skillOrigin][roleData.id] = {}
                end
                table.insert(passiveSkillsList[skillOrigin][roleData.id], { buffId = buffId, buffStar = buffStar })
            end
        end
    end

    -- 区域光环buff
    passiveSkillsList[Constants.PassiveBuffOrigin.RegionHalo] = self:MakeHaloBuffList()
    
    return passiveSkillsList
end

function UIBattlingCharactorBattleInfoDialog:MakeBuffDescVo(skillOrigin, buffId, buffStar)
    local buffData = Core:GetBuffData(buffId, buffStar, 1)
    local showIds = buffData.showIds
    if isNull(showIds) or #showIds <= 0 then return end -- 数组数据判断
    local showId = showIds[1] -- 子楠兄 Said ~~
    local buffEffectId = buffData.effects[1]
    local buffDes = BattleViewMgr:GetBuffInfo(buffEffectId, showId, buffStar, 1)
    if isNull(buffDes) then return end
    return {
        type = skillOrigin,
        buffDes = buffDes,
        buffValue = nil,
        buffType = 1,
        buffId = buffId,
    }
end

-- 获取第一波的光环buff
function UIBattlingCharactorBattleInfoDialog:MakeHaloBuffList()
    local haloBuffList = {}
    local battleSKill = BattleInfo.initData.battleSkill
    if isNull(battleSKill) then
        return haloBuffList
    end
    local firstWaveHaloSkills = battleSKill[1]
    if isNull(firstWaveHaloSkills) then
        return haloBuffList
    end

    for i, skillId in ipairs(firstWaveHaloSkills) do
        local buffInfoList = self:GetHaloSkillBuff(skillId)
        for i, buffInfo in ipairs(buffInfoList) do
            -- 获取buff的目标
            local targetType = buffInfo.targetType
            local roles = BattleMgr:GetAliveRoles( Constants.Camp.Two )
            local mainTarget = roles[1]
            local attackter = BattleMgr.agent
            local mainTargets = BattleMgr:SelectTargets(attackter, mainTarget, targetType)
            -- 填到buffList里
            for i, target in ipairs(mainTargets) do
                local roleBuffList = haloBuffList[target.id]
                if isNull(roleBuffList) then
                    roleBuffList = {}
                    haloBuffList[target.id] = roleBuffList
                end
                table.insert(roleBuffList, { buffId = buffInfo.buffId, buffStar = buffInfo.star })
            end
        end
    end
    return haloBuffList
end

--- 波次光环技能，获取技能里面的buff
---@param skillId number 技能Id
function UIBattlingCharactorBattleInfoDialog:GetHaloSkillBuff(skillId)
    local buffInfoList = {}
    local skill = Core:GetSkillData(skillId, 1, 1)
    -- 主效果，只取buff类型
    if skill.damageEffectType == 1 then
        local info = {
            targetType = skill.damageTarget,
            buffId = skill.damageEffect,
            star = 1,
        }
        table.insert(buffInfoList, info)
    end
    -- 子效果，只取buff类型
    for i, effect in ipairs(skill.subEffects) do
        if effect.effectType == 1 then
            local info = {
                targetType = effect.effectTarget == -1 and skill.damageTarget or effect.effectTarget,
                buffId = effect.effectId,
                star = effect.starEffect,
            }
            table.insert(buffInfoList, info)
        end
    end
    return buffInfoList
end

--- 设置选择buff图标的显示状态
---@param state any
function UIBattlingCharactorBattleInfoDialog:SetSelectBuffIconState(state, callback)
    for j = 1, #self.charactorInfoLBList do
        local roleId = self.charactorInfoLBList[j].Env.roleId
        local roleCamp = BattleMgr:GetRoleCampWithSpecialSummon(self.charactorInfoLBList[j].Env.roleId)
        if BattleInfo:IsUserCamp(roleCamp)
        and self.charactorInfoLBList[j].Env:GetCharactorAliveState()
        and not BattleMgr:IsSpecialSummonRole(roleId) then
            local LT_Role = self.charactorInfoLBList[j].Env
            LT_Role:SetSelectBuffIconState(state, callback)
        end
    end
end

function UIBattlingCharactorBattleInfoDialog:HasFatherBoss()
    return self.bossType == Constants.RoleClass.Boss
end

function UIBattlingCharactorBattleInfoDialog:HasBoss()
    return self.bossType >= Constants.RoleClass.Elite
end

function UIBattlingCharactorBattleInfoDialog:IsBoss(roleId)
    return self.bossId == roleId and self.bossType == Constants.RoleClass.Boss
end

function UIBattlingCharactorBattleInfoDialog:IsEliteOrBoss(roleId)
    return self.bossId == roleId
end

--- 初始化总伤害的节点和池子
function UIBattlingCharactorBattleInfoDialog:InitTotalDamage()
    self.totalDamage_unusedList = {}
    self.totalDamage_inusedList = {}

    local node = GetLuaBehaviour(self.TotalDamageNode.gameObject, "Game.UI.UIBattling.UIBattlingTotalDamage").Env
    table.insert(self.totalDamage_unusedList, node)
end

--- 获取一个未使用的总伤害节点
function UIBattlingCharactorBattleInfoDialog:GetUnusedTotalDamageNode()
    -- 先清理inusedList
    self:ClearInUsedList()

    -- 然后去unusedList里面找一个节点
    local getNode
    if #self.totalDamage_unusedList > 0 then
        getNode = table.remove(self.totalDamage_unusedList)
    end

    if isNotNull(getNode) then
        -- 找到了
        table.insert(self.totalDamage_inusedList, getNode)
    else
        -- 没找到
        local go = KTool.Instantiate(self.TotalDamageRoot.gameObject, self.TotalDamageNode.gameObject)
        getNode = GetLuaBehaviour(go, "Game.UI.UIBattling.UIBattlingTotalDamage").Env
        table.insert(self.totalDamage_inusedList, getNode)
    end

    return getNode
end

--- 检查正在使用中的list，把里面已经hide的节点拿出来，放到未使用中的list里
function UIBattlingCharactorBattleInfoDialog:ClearInUsedList()
    local unusedIndexList = {}
    for i, node in ipairs(self.totalDamage_inusedList) do
        if not node.isShow then
            table.insert(unusedIndexList, i)
        end
    end

    for i, index in fipairs(unusedIndexList) do
        local node = table.remove(self.totalDamage_inusedList, index)
        table.insert(self.totalDamage_unusedList, node)
    end
end

--- 隐藏总伤害面板
function UIBattlingCharactorBattleInfoDialog:HideAllTotalDamagePanel()
    for i, node in ipairs(self.totalDamage_inusedList) do
        node:HidePanel()
    end
end

return UIBattlingCharactorBattleInfoDialog
